//! §5.2 Q-MDRVMIX C1: rule X (`elaborate/src/mdrv_mix.rs`) — a variable of the target set (a module-level `logic` / `reg` /
//! `bit`, internal or output, not type-parameter-typed: the view's declaration fact) whose continuous writer (an `assign`, a
//! gate output, an instance port) and procedural writer (a blocking or non-blocking statement of `always_comb`, `always_ff`,
//! `always_latch`, `always`, `initial`, a declaration initializer, a subroutine inlined into one, or a frame body) write
//! overlapping decided bits is E3001, its text built from the two writes' own record only (`mdrv_mix.rs`, THE MESSAGE: the
//! variable's name, the bits of its packed value, each writer's kind words and each write's own position, `Write::at`).
//! The whole stdout, stderr and exit code of `vita` on the cell's files, as POST prints them:
//! - LOUD pins (rule X): the doc carries PRE's text (`W/wextpos/verify/bin/vita-post`, md5 0a9af60f, batch 6 row 1's POST),
//!   the IEEE clause with its line in `W/ref/ieee1800-2017.txt`, and each oracle's line (iverilog 13.0 -g2012 compile / vvp,
//!   verilator 5.054 --lint-only -Wall ; "an ERROR" / "lint WARNING" says which) ;
//! - PRE TEXT pins (rule Y, C2): the text PRE prints, unchanged by C1 ; C2 makes them E3001 ;
//! - QUIET pins: POST prints PRE's text ; the doc says why the rule does not fire (outside the target set, not a writer,
//!   no overlap, an older check already reported the variable or the elaboration latched an error, or a named residue).
//!
//! Cells: the parked build's 99 (W/mdrv/build/pins/LIST.c1.tsv: W/mdrv/ground/cells/m, W/mdrv/premise, premise2, plan, plan2,
//! W/mdrv/build/pins/new) ; the re-entry's N3 cells (W/mdrv2/ground/cells/q2, replay), F1's guards (q3), e2 (q7), w1-w3 (q6w),
//! the known silences (q5) ; W/wrext/fix1's forms (premise2/cells, cells_p2, premise/cells2, cells3, premise3/cells) ; premise
//! judge 1's a / r cells (W/mdrv2/premise/cells) ; wext_view.rs's three re-taken designs (`wv_`, R15 b), R17's (`r17_`) and
//! premise judge 2's e06 / e09 (W/mdrv2/premise2/cells/e, its literal line 11).
//! Generated by W/mdrv2/build/pins/gen2.py (its CHECK lines: W/mdrv2/build/pins/gen2.log).
use std::process::Command;
use std::sync::atomic::{AtomicU64, Ordering};

static NEXT: AtomicU64 = AtomicU64::new(0);

/// (stdout, stderr, exit code) of `vita <args>` in a temp dir of its own holding `files`.
fn run(files: &[(&str, &str)], args: &[&str]) -> (String, String, Option<i32>) {
    let n = NEXT.fetch_add(1, Ordering::Relaxed);
    let dir = std::env::temp_dir().join(format!("vita_mdrv_mix_pins_{}_{n}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    for (name, text) in files {
        std::fs::write(dir.join(name), text).unwrap();
    }
    let out = Command::new(env!("CARGO_BIN_EXE_vita"))
        .args(args)
        .current_dir(&dir)
        .output()
        .expect("run vita");
    let _ = std::fs::remove_dir_all(&dir);
    (
        String::from_utf8_lossy(&out.stdout).into_owned(),
        String::from_utf8_lossy(&out.stderr).into_owned(),
        out.status.code(),
    )
}

fn check_files(
    id: &str,
    files: &[(&str, &str)],
    args: &[&str],
    want_stdout: &str,
    want_stderr: &str,
    want_rc: i32,
) {
    let (so, se, rc) = run(files, args);
    assert_eq!(so, want_stdout, "{id}: stdout");
    assert_eq!(se, want_stderr, "{id}: stderr");
    assert_eq!(rc, Some(want_rc), "{id}: exit code");
}

fn check(id: &str, src: &str, want_stdout: &str, want_stderr: &str, want_rc: i32) {
    check_files(
        id,
        &[("t.sv", src)],
        &["t.sv"],
        want_stdout,
        want_stderr,
        want_rc,
    );
}

